import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Neo4j trend graph core","description":"","frontmatter":{},"headers":[],"relativePath":"feature/trend-graph-core/spec.md","filePath":"feature/trend-graph-core/spec.md"}'),n={name:"feature/trend-graph-core/spec.md"};function d(s,e,i,c,p,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="neo4j-trend-graph-core" tabindex="-1">Neo4j trend graph core <a class="header-anchor" href="#neo4j-trend-graph-core" aria-label="Permalink to &quot;Neo4j trend graph core&quot;">​</a></h1><h2 id="objective-and-acceptance-criteria" tabindex="-1">Objective and acceptance criteria <a class="header-anchor" href="#objective-and-acceptance-criteria" aria-label="Permalink to &quot;Objective and acceptance criteria&quot;">​</a></h2><p>Provide a read-only backend for a future Bloom-style explorer of the public trend graph. This phase changes no UI, Chroma, scoring, ingestion, schema or stored data. An active Admin can search persisted Trends, inspect the graph vocabulary, and retrieve a bounded neighborhood around a Trend. These are Neo4j records, not the Redis published ranking; a stored Trend may not be in a published top list.</p><p>Nodes include Trend, CrawledPost and evidenced Entity subtypes. Restrict traversal to BELONGS_TO, MENTIONS and ASSOCIATED_WITH and nodes without a brand namespace. Only Trend IDs beginning <code>trend:</code> are eligible. Do not expose private RAG graphs. Return node/edge IDs, labels/type, selected properties, directed source/target, counts, requested depth, and explicit truncation reasons. Preserve parallel edges. IDs based on Neo4j elementId are opaque and valid for the existing graph lifetime; clients must refetch after database recreation, not persist these as business IDs.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>Business endpoints, all GET under <code>/api/v1/admin/ai/trend-graph</code>:</p><ul><li><code>/catalog</code>: fixed supported labels, relationships and request limits.</li><li><code>/trends?q=&amp;date=YYYY-MM-DD&amp;offset=0&amp;limit=20</code>: bounded search with hasMore.</li><li><code>/neighborhood?trendId=trend:...&amp;depth=2&amp;maxNodes=100&amp;maxEdges=200&amp;fanout=25</code>.</li><li><code>/nodes?q=&amp;label=&amp;date=YYYY-MM-DD&amp;offset=0&amp;limit=20</code>: search eligible public nodes, optionally restricted to a supported label. Date matches stored n.date.</li><li><code>/expand?nodeId=...&amp;depth=1&amp;maxNodes=100&amp;maxEdges=200&amp;fanout=25</code>: center the bounded neighborhood on an eligible public node by elementId or business ID.</li></ul><p>AI exposes the same suffixes under <code>/api/v1/ai/graph/explorer</code>, protected by the existing internal key. Business wraps results in ApiResponse. Search uses literal case-insensitive text, no user Cypher, and date matches Trend.date exactly. Limits: depth 1..2, nodes 1..200, edges 1..400, fanout 1..50, page 1..100, offset 0..10000, q &lt;=100, trendId &lt;=300. Unknown Trend returns 404; disconnected existing Trend returns one real node. Invalid input returns 400/422. Neo4j failure or timeout returns structured 503, never an empty-success or synthetic node. The legacy graph read must also stop hiding failures; existing write APIs remain.</p><p>Search returns <code>{items, offset, limit, hasMore}</code> without an expensive exact count. Each node has <code>{id, businessId, name, labels, type, properties, propertiesTruncated}</code>; each edge has <code>{id, source, target, type, properties, propertiesTruncated}</code>. Graph returns <code>{trendId, rootId, nodes, edges, nodeCount, edgeCount, depth, maxNodes, maxEdges, fanout, truncated, truncationReasons}</code>. Properties use a public allowlist, omit non-finite numbers and cap each text value at 4000 characters. No arbitrary node-property dump.</p><p><code>truncationReasons</code> can contain <code>FANOUT_LIMIT</code>, <code>NODE_LIMIT</code> or <code>EDGE_LIMIT</code>. <code>truncated=false</code> means no additional safety limit was encountered within the requested depth and supported vocabulary; it never claims to include the entire database. Fanout flags conservatively report omitted adjacency rows, even if an edge might also be visible from another expanded node. Expansion from a selected public node keeps the same visibility rules, vocabulary and depth 1..2 bounds. No unrestricted Cypher or private brand-graph access is exposed.</p><h2 id="definition-of-done-out-of-scope" tabindex="-1">Definition of done / out of scope <a class="header-anchor" href="#definition-of-done-out-of-scope" aria-label="Permalink to &quot;Definition of done / out of scope&quot;">​</a></h2><p>Pass isolated validation, traversal/security/error tests, Business compile and read-only live Neo4j smoke checks if available. No new test artifacts committed; local checks belong in ignored keep-local-only. No migration, seeding, graph editing, arbitrary query API, automatic restart, Bloom UI, vector plot or push.</p>',12)])])}const m=a(n,[["render",d]]);export{h as __pageData,m as default};
